export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
  name: string;
  title?: string;
  description?: string;
  inputSchema: JsonSchema;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
    untrustedContentHint?: boolean;
    consequentialHint?: boolean;
    [key: string]: unknown;
  };
}
export interface Execution {
  id: string;
  name: string;
  source: "human" | "agent" | "simulator";
  status: "running" | "success" | "error" | "cancelled";
  startedAt: number;
  completedAt?: number;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  progress?: { progress: number; total?: number; message?: string };
}
export type Support = "checking" | "native" | "legacy" | "unsupported";
export interface ToolContext {
  signal: AbortSignal;
  source: Execution["source"];
}
export interface WebTool extends ToolDefinition {
  execute: (
    args: Record<string, unknown>,
    context: ToolContext,
  ) => unknown | Promise<unknown>;
}
export function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "The operation failed.";
}

"use client";
import { useRef, useState, type ComponentProps, type FormEvent } from "react";
import { errorMessage } from "@/lib/mcp/types";
type AgentSubmit = SubmitEvent & {
  agentInvoked?: boolean;
  respondWith?: (value: Promise<unknown>) => void;
};
export function WebMCPForm({
  toolName,
  toolDescription,
  autoSubmit = false,
  onExecute,
  children,
  ...props
}: Omit<ComponentProps<"form">, "onSubmit"> & {
  toolName: string;
  toolDescription: string;
  autoSubmit?: boolean;
  onExecute: (
    data: FormData,
    context: { agentInvoked: boolean },
  ) => Promise<unknown>;
}) {
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const busy = useRef(false);
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const native = event.nativeEvent as AgentSubmit;
    if (busy.current) {
      if (native.agentInvoked)
        native.respondWith?.(
          Promise.resolve({ error: "A submission is already running." }),
        );
      return;
    }
    busy.current = true;
    setPending(true);
    setError("");
    const data = new FormData(event.currentTarget, native.submitter);
    const response = Promise.resolve()
      .then(() =>
        onExecute(data, { agentInvoked: native.agentInvoked === true }),
      )
      .catch((e) => {
        setError(errorMessage(e));
        return { error: errorMessage(e) };
      })
      .finally(() => {
        busy.current = false;
        setPending(false);
      });
    if (native.agentInvoked) native.respondWith?.(response);
  }
  return (
    <form
      {...props}
      {...{
        toolname: toolName,
        tooldescription: toolDescription,
        ...(autoSubmit ? { toolautosubmit: "" } : {}),
      }}
      onSubmit={submit}
      aria-busy={pending}
    >
      {children}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
    </form>
  );
}
export function toolField(description: string) {
  return { toolparamdescription: description };
}
